import React from "react";

const ciri = [
  'Alamat pengirim aneh',
  'Bahasa mendesak',
  'Link mencurigakan',
  'Lampiran tidak relevan',
  'Tampilan mirip asli',
];

export default function Slide5CiriPhishing({ onNext, onPrev }) {
  return (
    <div className="slide-content">
      <h2 className="slide-title mb-6">Ciri-ciri Email Phishing</h2>
      <ul className="text-lg text-white/90 mb-8 space-y-3">
        {ciri.map((c, i) => (
          <li key={i} className="flex items-center gap-3"><span className="text-[#FF7F00]">▶</span>{c}</li>
        ))}
      </ul>
      <div className="flex gap-4 justify-center">
        <button onClick={onPrev} className="bg-gray-200 text-orange-700 px-4 py-2 rounded-lg font-bold hover:bg-gray-300 transition">Back</button>
        <button onClick={onNext} className="bg-[#FF7F00] text-white px-6 py-2 rounded-lg font-bold text-lg shadow hover:bg-orange-600 transition">Next</button>
      </div>
    </div>
  );
}
